import os, re, json

def load():
    d = os.environ.get('RLM_SESSION_DIR', '')
    session_file = os.path.join(d, '..', '..', 'sessions', os.path.basename(d) + '.jsonl')
    t = open(session_file).read()

    # Parse all grids for this task
    task_id = 'task-8caaa084'
    task_grids = {}

    # Find all demo inputs/outputs and test input
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n(.*?)(?=Demo pair|Test input|$)', re.DOTALL, t):
        full_key = m[1]
        height, width = int(m[2]), int(m[3])
        content = m[4].strip()

        # Parse the grid
        rows = []
        for line in content.split('\n')[:height]:
            if line.strip():
                rows.append([int(x) for x in line.split()])

        if full_key.startswith('Test input'):
            task_grids['test'] = rows
        else:
            task_grids[full_key] = rows

    return task_grids

grids = load()
